function translateHtml(html){if(state.user?.language!=='Tagalog')return html;const template=document.createElement('template');template.innerHTML=html;const walker=document.createTreeWalker(template.content,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){let value=node.nodeValue;for(const [en,tl] of UI_TRANSLATIONS)value=value.replaceAll(en,tl);node.nodeValue=value}return template.innerHTML}

async function api(path, options={}){
  const res=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});
  const data=await res.json().catch(()=>({error:'Unexpected server response.'}));
  if(!res.ok)throw new Error(data.error||'Request failed.'); return data;
}
function notify(message){const el=$('#toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('show'),3000)}
function shortName(name=''){return name.trim().split(/\s+/).slice(0,2).map(w=>w[0]||'').join('').toUpperCase()||'N'}
function isTeacher(){return state.user?.role==='teacher'}
async function sync(){if(!state.user)return;try{const p=await api('/api/profile');state.profile=p;state.user=p.user;state.xp=p.xp;if(state.user.role==='student'){const d=await api('/api/lessons');state.lessons=d.lessons;state.xp=d.xp}}catch(e){if(e.message.includes('sign in')){const role=state.user?.role;state.user=null;state.page=role==='teacher'?'Teacher Login':'Student Login'}}}
async function start(){try{const d=await api('/api/session');state.demo=d.demo_enabled;state.volatile=d.volatile_data;state.user=d.user;if(state.user){state.page=state.user.role==='teacher'?'Teacher Dashboard':'Home';await sync();if(state.user?.role==='teacher'){try{const st=await api('/api/teacher/students');state.students=st.students;state.studentsLoaded=true}catch{state.students=[];state.studentsLoaded=true}}}}catch{}render()}
function render(){document.body.classList.toggle('dark-theme',state.user?.theme==='Dark');const app=$('#app');if(!state.user){app.innerHTML=translateHtml(authPage());bindAuth();return}app.innerHTML=translateHtml(layout(pageContent()));bindShell();bindPage();}
function authPage(){const teacher=state.page==='Teacher Login',register=state.page==='Student Registration'||state.page==='Teacher Registration',teacherRegister=state.page==='Teacher Registration';return `<main class="auth-wrap"><section class="auth-card"><div class="auth-brand-panel"><span class="decor d1">＋</span><span class="decor d2">⌗</span><span class="decor d3">✳</span><img class="school-seal" src="assets/school-seal.png" alt="Crescencia Drucila Lopez Senior High School seal"><div class="brand-big">Numi<span>Quest</span></div><div class="brand-slogan">Learn <b>·</b> Play <b>·</b> Grow</div></div><div class="auth-form-panel"><form class="auth-form" id="auth-form"><h1>${register?(teacherRegister?'Teacher Registration':'Student Registration'):(teacher?'Teacher/Admin Login':'Student Login')}</h1><p>${register?'Create your account and start your learning journey.':teacher?'Welcome back! Sign in to manage your class.':'Welcome back! Log in to continue your learning journey.'}</p><input type="hidden" name="role" value="${teacher||teacherRegister?'teacher':'student'}">${register?authField('Full Name','text','name','♙',true):''}${authField('Email Address','email','email','✉',true)}${register?authField('Password','password','password','▣',true):authField('Password','password','password','▣',true)}${register?authField('Confirm Password','password','confirm','▣',true):''}${register&&!teacherRegister?authField('Grade Level (type manually)','text','grade','▦',true)+authField('Section (type manually)','text','section','▦',true):''}${register?`<label class="remember-row"><span><input type="checkbox" name="terms" required> I agree to the Terms and Conditions</span></label>`:`<div class="remember-row"><label><input type="checkbox" checked> Remember Me</label><a href="#" id="forgot-link">Forgot Password?</a></div>`}<button class="button ${teacher?'':'orange'}" type="submit">${register?'Register':'Login'}</button><div class="auth-foot">${register?'Already have an account?':"Don't have an account?"} <button class="link-button" type="button" data-auth="${register?(teacherRegister?'Teacher Login':'Student Login'):(teacher?'Teacher Registration':'Student Registration')}">${register?'Login':teacher?'Register':'Register'}</button></div><div class="auth-switch">${teacher?'<button type="button" data-auth="Student Login">Student Login</button>':'<button type="button" data-auth="Teacher Login">Teacher / Admin</button>'}${state.demo&&teacher?'<button type="button" id="demo-fill">Use local demo account</button>':''}${teacherRegister?'<p class="small muted">Teacher registration requires @deped.gov.ph and administrator approval.</p>':''}</div></form></div></section>${state.volatile?'<p class="volatile-notice">Free public preview: account and learning progress may reset when the service restarts.</p>':''}</main>`}
function authField(label,type,name,icon,required=false){return `<div class="field"><div class="input-wrap"><span class="input-symbol">${icon}</span><input class="form-control" type="${type}" name="${name}" placeholder="${label}" ${required?'required':''} autocomplete="${name==='password'?'current-password':name==='email'?'email':'off'}">${type==='password'?`<button class="eye-toggle" type="button" aria-label="Show password" data-toggle-pass>◉</button>`:''}</div></div>`}
function layout(content){const nav=isTeacher()?TEACHER_NAV:STUDENT_NAV;return `<div class="shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#" data-page="${isTeacher()?'Teacher Dashboard':'Home'}"><img class="brand-mark" src="assets/school-seal.png" alt="Crescencia Drucila Lopez Senior High School seal"><span><span class="brand-name">Numi<span>Quest</span></span><span class="brand-tag">LEARN · PLAY · GROW</span></span></a><nav class="nav">${nav.map(([n,i])=>`<button class="${state.page===n?'active':''}" data-page="${n}"><span class="nav-icon">${navIcon(i)}</span>${label(n)}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="side-student"><span class="mini-avatar">${state.user.avatar?`<img src="${state.user.avatar}" alt="">`:shortName(state.user.name)}</span><span><b>${esc(state.user.name)}</b><small>${isTeacher()?'Teacher':`Grade ${esc(state.user.grade)} · ${esc(state.user.section)}`}</small></span></div></div></aside><main class="content"><header class="topbar"><div style="display:flex;align-items:center;gap:10px"><button class="icon-btn menu-toggle" id="menu-toggle" aria-label="Open menu" aria-controls="sidebar" aria-expanded="false">☰</button><div><h1 class="page-title">${pageTitle()}</h1><p class="page-subtitle">${pageSubtitle()}</p></div></div><div class="top-actions">${isTeacher()?'':`<span class="pill">⭐ <strong>${state.xp} XP</strong></span>`}<button class="icon-btn" data-page="${isTeacher()?'Teacher Profile':'Profile'}" aria-label="Open profile">${navIcon('user')}</button></div></header>${content}</main></div>${state.modal?modalHTML():''}`}
function pageTitle(){if(state.page==='Learning Map')return label(state.page);return label(state.page)}
function pageSubtitle(){const m={Home:['Your learning adventure continues!','Tuloy ang iyong paglalakbay sa pagkatuto!'],Lessons:['Learn, practice, and improve your numeracy skills.','Matuto at magsanay sa General Mathematics.'], 'Learning Map':['Your learning journey, one lesson at a time.','Sundan ang iyong pagkatuto, aralin kada aralin.'],Games:['Play games and sharpen your math skills.','Maglaro at hasain ang iyong kaalaman sa Math.'],Garden:['Grow a garden with your learning points.','Palaguin ang iyong hardin gamit ang XP.'],Profile:['Your progress and achievements.','Tingnan ang iyong progreso at mga tagumpay.'],Settings:['Make NumiQuest feel like yours.','Iangkop ang NumiQuest sa iyong gusto.'], 'Teacher Dashboard':['Hi, Teacher! Welcome to NumiQuest.','Kumusta, Guro! Maligayang pagdating sa NumiQuest.'],Students:['Track your students’ progress.','Subaybayan ang progreso ng mga mag-aaral.'],'Lesson Management':['Organize your class lessons.','Pamahalaan ang mga aralin ng klase.'],'Teacher Profile':['Your teaching profile and account.','Profile at account ng guro.']};return text(...(m[state.page]||['','']))}
function pageContent(){switch(state.page){case'Home':return homePage();case'Lessons':return lessonsPage();case'Lesson':return lessonPage();case'Quiz':return quizPage();case'Quiz Result':return resultPage();case'Learning Map':return mapPage();case'Games':return gamesPage();case'Garden':return gardenPage();case'Profile':return profilePage();case'Settings':return settingsPage();case'Teacher Dashboard':return teacherDashboard();case'Students':return studentsPage();case'Student Details':return studentDetailPage();case'Lesson Management':return lessonManagement();case'Teacher Profile':return teacherProfile();default:return homePage()}}
const progressCount=()=>state.lessons.filter(l=>l.completed).length;
function homePage(){const quizCount=state.lessons.filter(l=>l.attempted).length;return `<section class="hero-row"><div class="welcome"><div class="avatar">${state.user.avatar?`<img src="${state.user.avatar}" alt="Profile photo">`:shortName(state.user.name)}</div><div><h2>Hi, ${esc(state.user.name.split(' ')[0])}!</h2><p>Grade ${esc(state.user.grade)} · ${esc(state.user.section)}</p></div></div><div class="stats"><div class="stat"><span class="stat-icon">⭐</span><div><strong>${state.xp}</strong><span>XP earned</span></div></div><div class="stat"><span class="stat-icon">🛡️</span><div><strong>Level ${Math.floor(state.xp/250)+1}</strong><span>${state.xp%250} / 250 XP</span></div></div></div></section><section class="card"><h2 class="card-title">My Progress</h2><div class="progress-grid"><div class="progress-item"><div class="big-icon">🏅</div><strong>${progressCount()}/6</strong><span>Lessons Completed</span></div><div class="progress-item"><div class="big-icon">🎯</div><strong>${quizCount}/6</strong><span>Quizzes Completed</span></div><div class="progress-item"><div class="big-icon">💙</div><strong>${state.lessons.filter(l=>l.unlocked).length}</strong><span>Lessons Unlocked</span></div><div class="progress-item"><div class="big-icon">🌱</div><strong>${state.garden?.plots.filter(p=>p.stage>0).length||0}/3</strong><span>Plants Growing</span></div></div></section><section class="card garden-banner"><span class="garden-emoji">🌳</span><div style="flex:1"><b>Virtual Garden</b><div class="small muted">${state.garden?.plots.filter(p=>p.stage>0).length||0}/3 Plants Growing</div><div class="growline"><i style="width:${(state.garden?.plots.filter(p=>p.stage>0).length||0)/3*100}%"></i></div></div><button class="button light small-btn" data-page="Garden">View Garden</button></section><section class="grid grid-2"><div class="card"><h2 class="card-title">Recent Achievements</h2><div class="grid grid-3"><div class="achievement"><span>🎖️</span><small>Math Beginner</small></div><div class="achievement"><span>${quizCount?'💎':'🔒'}</span><small>Quiz Star</small></div><div class="achievement"><span>${quizCount>=3?'🏆':'🔒'}</span><small>Game Champ</small></div></div></div><div class="card"><h2 class="card-title">Learning Progress</h2><div class="activity-list">${state.lessons.map(l=>`<div class="activity"><span class="activity-icon">${l.completed?'✓':l.unlocked?'○':'🔒'}</span><span>${esc(l.title)}</span><span class="badge ${l.completed?'passed':l.unlocked?'locked':'locked'}">${l.completed?'Done':l.unlocked?'Ready':'Locked'}</span></div>`).slice(0,4).join('')}</div></div></section>`}
function lessonsPage(){return `<section class="card"><h2 class="card-title">Lessons</h2><p class="muted small">Grade 11 · General Mathematics</p><div class="row-list">${state.lessons.map((l,i)=>`<div class="lesson-row"><span class="lesson-icon ${l.completed?'done':''}">${l.completed?'✓':'▤'}</span><div class="lesson-info"><strong>Lesson ${i+1}. ${esc(l.title)}</strong><small>⭐ 100 XP for lesson completion · ${l.xp} XP per correct answer · 10-question quiz</small></div>${l.attempted?`<button class="badge ${l.attempt.passed?'passed':'failed'}" data-action="show-result" data-index="${i}">${l.attempt.passed?'Completed':'View Result'}</button>`:l.unlocked?`<button class="button small-btn" data-action="open-lesson" data-index="${i}">${label('Start Lesson')}</button>`:`<span class="badge locked">🔒 ${label('Locked')}</span>`}</div>`).join('')}</div></section>`}
function lessonPage(){const l=state.lessons.find(x=>x.id===state.openLesson);if(!l)return lessonsPage();return `<section class="card"><div class="between"><div><span class="badge locked">LESSON ${l.id}</span><h2 style="margin:9px 0 3px">${esc(l.title)}</h2><p class="muted small">Grade 11 · General Mathematics</p></div><button class="button light small-btn" data-page="Lessons">← Back to Lessons</button></div><hr style="border:0;border-top:1px solid var(--line);margin:14px 0"><h3 class="card-title">Learning Objectives</h3><ul class="lesson-objectives">${l.objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul><h3 class="card-title">Concept</h3><p class="lesson-copy">${esc(l.concept)}</p><div class="formula-box"><b>Key idea</b><br>${esc(l.formula)}</div><h3 class="card-title" style="margin-top:17px">Worked Example</h3><p class="lesson-copy">${esc(l.example)}</p><label class="read-check"><input type="checkbox" id="lesson-read"> I have read and understood this lesson.</label><div class="between" style="margin-top:16px"><span class="muted small">When ready, mark this lesson complete to continue to its quiz.</span><button class="button orange" id="complete-lesson">Mark Lesson Complete</button></div></section>`}
function quizPage(){const lesson=state.lessons.find(x=>x.id===state.openLesson);if(!lesson||!state.quiz)return `<section class="card loading-state" role="status" aria-live="polite">Loading quiz…</section>`;return `<section class="card"><div class="quiz-top"><strong>Quiz ${lesson.id}: ${esc(lesson.title)}</strong><span class="muted">10 Questions · Fixed Order</span></div><hr style="border:0;border-top:1px solid #e1eff6;margin:14px 0"><p class="muted small">Answer every question. You have one attempt for this quiz.</p><div class="all-questions">${state.quiz.questions.map((q,qi)=>`<fieldset class="question-block"><legend><b>${qi+1}.</b> ${esc(q.text)}</legend><div class="question-options">${q.options.map((o,oi)=>`<label class="quiz-option ${state.quizAnswers[qi]===oi?'selected':''}"><input type="radio" name="q${qi}" value="${oi}" ${state.quizAnswers[qi]===oi?'checked':''}>${esc(o)}</label>`).join('')}</div></fieldset>`).join('')}</div><div id="quiz-warning"></div><div class="between" style="margin-top:14px"><button class="button light" data-page="Lessons">Save & Exit</button><span class="muted small">Passing score: 70%</span><button class="button green" id="submit-quiz">Submit Quiz</button></div></section>`}
function resultPage(){const r=state.result||state.lessons.find(l=>l.id===state.openLesson)?.attempt;if(!r)return lessonsPage();const lid=state.openLesson||1,l=state.lessons.find(x=>x.id===lid);return `<section class="card center"><div class="result-trophy">${r.passed?'🏆':'📘'}</div><h2 style="margin:0">Quiz ${r.passed?'Completed':'Results'}</h2><p class="score">Your Score: ${r.score}%</p><p class="muted">Correct Answers: ${r.correct} / ${r.total} · Submitted ${r.submitted_at?new Date(r.submitted_at*1000).toLocaleString():''}</p><span class="badge ${r.passed?'passed':'failed'}" style="font-size:13px;padding:8px 24px">${r.passed?'Passed':'Failed · Review the lesson'}</span><p class="small muted">${r.passed?`XP earned: ${r.xp_earned??r.correct*l.xp}`:'A quiz can only be submitted once. Review the lesson content to prepare for the next unit.'}</p></section><section class="card"><h2 class="card-title">Review Answers</h2><div class="row-list">${state.quiz?.questions?state.quiz.questions.map((q,i)=>answerReview(q,r,i)).join(''):answerReviewFromLesson(r,lid)}</div><button class="button" style="width:100%;margin-top:14px" data-page="Lessons">Back to Lessons</button></section>`}
function answerReview(q,r,i){const picked=r.answers?.[i],correct=r.key?.[i];return `<div class="lesson-row"><div class="lesson-info"><strong>${i+1}. ${esc(q.text)}</strong><small>Your answer: ${esc(q.options[picked]??'—')} · Correct: ${esc(q.options[correct])}<br>${esc(r.explanations?.[i]||'')}</small></div><b style="color:${picked===correct?'#21a562':'#e26262'}">${picked===correct?'✓':'×'}</b></div>`}
function answerReviewFromLesson(r,lid){const q=state.quiz?.questions||[];return q.map((v,i)=>answerReview(v,r,i)).join('')||'<p class="muted">The saved score is available. Start a new session to review question explanations.</p>'}
function mapPage(){
 const thresholds=[0,100,250,450,700,1000];
 const lessons=state.lessons||[];
 const firstIncomplete=lessons.findIndex(l=>!l.completed);
 const nextIndex=firstIncomplete<0?Math.max(0,lessons.length-1):firstIncomplete;
 const next=lessons[nextIndex];
 const threshold=thresholds[nextIndex]||0;
 const percent=next?.completed?100:threshold===0?100:Math.min(100,Math.round(state.xp/threshold*100));
 return `<section class="card map-overview"><h2 class="card-title">Learning Map</h2><div class="map-path" role="list">${lessons.map((l,i)=>`<div class="map-stop ${l.completed?'complete':l.unlocked?'current':'locked'}" role="listitem" aria-label="${esc(l.title)} · ${l.completed?'Completed':l.unlocked?'Available':`Unlock at ${thresholds[i]} XP`}" ${l.unlocked&&!l.completed?'aria-current="step"':''}><span class="stop-circle">${l.completed?'<span aria-hidden="true">✓</span>':l.unlocked?i+1:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>'}</span><strong>${esc(l.title.split(' ')[0])}</strong><small>${l.unlocked?`${state.xp}/${thresholds[i]} XP`:`${thresholds[i]} XP`}</small></div>`).join('')}</div></section><section class="card map-next"><div class="between map-next-heading"><div><h2 class="card-title">Next Lesson</h2><p class="muted small">Current XP balance: <b>${state.xp} XP</b></p></div><button class="button light small-btn" data-page="Lessons">View Lessons</button></div>${next?`<div class="next-lesson-feature"><span class="next-lesson-icon">${navIcon('book')}</span><div class="lesson-info"><strong>${nextIndex+1}. ${esc(next.title)}</strong><small>${next.unlocked?'Available now':`Unlock at ${threshold} XP`}</small></div><span class="badge ${next.completed?'passed':next.unlocked?'done':'locked'}">${next.completed?'Done':next.unlocked?'Open':'Locked'}</span></div><div class="map-next-progress"><div class="growline"><i style="width:${percent}%"></i></div></div>`:''}</section>`
}
const GAMES=[['🧮','Integer Challenge'],['🏎️','Rational Race'],['🧩','Percentage Patch'],['⚖️','Algebra Quest'],['⏱️','Equation Sprint'],['🔍','Problem Solving']];
function gamesPage(){return `<section class="page-grid">${GAMES.map(([icon,name],i)=>{const l=state.lessons[i];return `<article class="game-card"><span class="game-icon">${icon}</span><h3>${name}</h3><p>${l.attempt?.passed?'Quiz passed · Ready to play':`Pass Lesson ${i+1} quiz to unlock`}</p>${l.attempt?.passed?`<button class="button small-btn" data-action="play-game" data-index="${i}">Play</button>`:`<span class="badge locked">🔒 Locked</span>`}</article>`}).join('')}</section>`}
function gardenPage(){if(!state.garden)return `<section class="card loading-state" role="status" aria-live="polite">Loading garden…</section>`;return `<section class="card"><div class="between"><h2 class="card-title">My Garden</h2><b class="small">🌟 ${state.garden.plots.filter(p=>p.stage>0).length} Plants &nbsp; <span style="color:#f39315">${state.garden.xp} XP</span></b></div><p class="muted small">Seed: 100 XP · Water: 10 XP · Fruit at stage 6: +30 XP</p><div class="page-grid">${state.garden.plots.map((p,i)=>`<article class="plant-card"><div class="plant-art plant-stage">${p.stage===0?'🌫️':p.stage<3?'🌱':p.stage<6?'🌳':'🍊'}</div><h3>${esc(p.plant||['Mango','Rambutan','Lanzones'][i])}</h3><p>${p.stage?['','Seed','Sprout','Young Plant','Growing Plant','Mature Tree','Fruit-Bearing Tree'][p.stage]:'Empty plot'}${p.stage?` · ${p.stage}/6`:''}</p><div class="growline"><i style="width:${p.stage/6*100}%"></i></div>${p.stage===0?`<button class="button light small-btn" data-action="garden" data-kind="plant" data-index="${i}">🌱 Plant seed · 100 XP</button>`:p.stage<6?`<button class="button light small-btn" data-action="garden" data-kind="water" data-index="${i}">💧 Water · 10 XP</button>`:`<span class="badge passed">Fruit earned ${p.fruit_claimed?'✓':''}</span>`}</article>`).join('')}</div></section><section class="card"><h2 class="card-title">Growth Stages</h2><div class="requirement">${['Seed','Sprout','Young Plant','Growing','Mature','Fruit'].map((v,i)=>`<div>${v}<strong>Stage ${i+1}</strong></div>`).join('')}</div></section>`}
function profilePage(){return profileCard(false)}
function teacherProfile(){return profileCard(true)}
function profileCard(teacher){const p=state.profile||{};const u=p.user||state.user;return `<section class="card"><div class="profile-top"><div class="avatar profile-avatar">${u.avatar?`<img src="${u.avatar}" alt="Profile photo">`:shortName(u.name)}</div><div><h2 style="margin:0;font-size:20px">${esc(u.name)}</h2><div class="small muted">${teacher?'Teacher · Mathematics':`Grade ${esc(u.grade)} · ${esc(u.section)}`}</div><div class="small muted">${esc(u.email)}</div><div class="small muted">Role: ${esc(u.role)}</div></div></div><div class="level-track"><div class="between small"><b>Level ${Math.floor(state.xp/250)+1}</b><span>${state.xp} / ${(Math.floor(state.xp/250)+1)*250} XP</span></div><div class="meter"><i style="width:${state.xp%250/2.5}%"></i></div></div><button class="button light small-btn" data-action="edit-profile">Edit Profile</button></section>${teacher?'':`<section class="card"><h2 class="card-title">Learning Stats</h2><div class="progress-grid"><div class="progress-item"><strong>${p.completed?.length||0}</strong><span>Lessons</span></div><div class="progress-item"><strong>${p.attempts?.length||0}</strong><span>Quizzes</span></div><div class="progress-item"><strong>${p.attempts?.length?Math.round(p.attempts.reduce((a,x)=>a+x.score,0)/p.attempts.length):0}%</strong><span>Average Score</span></div><div class="progress-item"><strong>${state.xp}</strong><span>Total XP</span></div></div></section>`}<section class="card"><h2 class="card-title">Change Password</h2><form id="password-form"><div class="grid grid-3"><input class="form-control" type="password" name="current_password" placeholder="Current password" required><input class="form-control" type="password" name="new_password" placeholder="New password (8+ characters)" required minlength="8"><input class="form-control" type="password" name="confirm_password" placeholder="Confirm new password" required minlength="8"></div><button class="button small-btn" style="margin-top:12px">Update Password</button></form></section>`}
function settingsPage(){return `<form class="card" id="settings-form"><h2 class="card-title">Settings</h2><div class="settings-section"><h3>Language Options</h3><div class="choice-row">${['English','Tagalog'].map(x=>`<label class="choice"><input type="radio" name="language" value="${x}" ${state.user.language===x?'checked':''}>${x}</label>`).join('')}</div></div><div class="settings-section"><h3>Theme</h3><div class="choice-row">${['Light','Dark'].map(x=>`<label class="choice"><input type="radio" name="theme" value="${x}" ${state.user.theme===x?'checked':''}>${x}</label>`).join('')}</div></div><button class="button setting-save">${label('Save Changes')}</button></form>`}
function teacherDashboard(){if(!state.students.length&&!state.studentsLoaded)return `<section class="card loading-state" role="status" aria-live="polite">Loading class data…</section>`;const ss=state.students;const scored=ss.filter(s=>s.avg_score!==null);const attemptCount=ss.reduce((n,s)=>n+s.quizzes,0);const avg=attemptCount?Math.round(ss.reduce((n,s)=>n+(s.avg_score||0)*s.quizzes,0)/attemptCount):null;const day=Math.floor(Date.now()/86400);const active=ss.filter(s=>s.last_active&&Math.floor(s.last_active/86400)===day).length;const done=ss.filter(s=>s.completed>=6).length;const loginEvents=ss.reduce((n,s)=>n+(s.login_events||0),0);return `<section class="card"><h2 class="card-title">Hi, ${esc(state.user.name)}! Welcome to NumiQuest.</h2><p class="muted small">Teacher Dashboard · Class records from this app</p><div class="progress-grid">${[[ss.length,'Registered Students'],[active,'Students logged in today'],[ss.filter(s=>s.quizzes>0).length,'Students with quizzes'],[attemptCount,'Quiz Submissions']].map(([n,l])=>`<div class="progress-item"><strong style="color:#1287db">${n}</strong><span>${l}</span></div>`).join('')}</div><p class="muted small">${loginEvents} total login events recorded · ${done} students completed all 6 lessons.</p></section><section class="grid grid-3"><div class="card center"><h3 class="card-title">Average Quiz Score</h3><div class="score">${avg===null?'—':avg+'%'}</div><div class="muted small">${attemptCount} submitted quizzes from ${scored.length} students</div></div><div class="card center"><h3 class="card-title">Students Passed</h3><div class="score" style="color:#26a661">${ss.filter(s=>s.avg_score>=70).length}</div><div class="muted small">Based on student average</div></div><div class="card center"><h3 class="card-title">Students Needing Help</h3><div class="score" style="color:#f3901a">${ss.filter(s=>s.avg_score!==null&&s.avg_score<70).length}</div><div class="muted small">Average below 70%</div></div></section><section class="card"><div class="between"><h2 class="card-title">Student Records</h2><button class="button light small-btn" data-page="Students">View Students</button></div>${ss.length?studentTable(ss.slice(0,5)):empty('No students have registered yet. Student accounts will appear here after registration.')}</section>`}
function studentTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Student</th><th>Grade</th><th>Section</th><th>Lessons</th><th>Quizzes</th><th>Avg. Score</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td><button class="table-link" data-action="student-detail" data-id="${s.id}">${s.avatar?`<img class="table-avatar" src="${s.avatar}" alt="">`:''}${esc(s.name)}</button></td><td>${esc(s.grade)}</td><td>${esc(s.section)}</td><td>${s.completed}/6</td><td>${s.quizzes}</td><td>${s.avg_score===null?'—':Math.round(s.avg_score)+'%'}</td><td><button class="button light small-btn" data-action="student-detail" data-id="${s.id}">Details</button></td></tr>`).join('')}</tbody></table></div>`}
function studentsPage(){const q=state.search.toLowerCase();const rows=state.students.filter(s=>`${s.name} ${s.grade} ${s.section}`.toLowerCase().includes(q)&&(!state.status||(state.status==='Needs help'?(s.avg_score!==null&&s.avg_score<70):state.status==='Passed'&&s.avg_score>=70)));return `<section class="card"><h2 class="card-title">Student List</h2><div class="search-row"><input id="student-search" class="form-control" value="${esc(state.search)}" placeholder="⌕  Search by name, grade, or section…"><select id="status-filter" class="form-control" style="max-width:170px"><option value="">All Students</option><option ${state.status==='Passed'?'selected':''}>Passed</option><option ${state.status==='Needs help'?'selected':''}>Needs help</option></select></div>${rows.length?studentTable(rows):empty('No matching student records. Student results only show registered accounts.')}</section>`}
function studentDetailPage(){const d=state.studentDetail;if(!d)return `<section class="card loading-state" role="status" aria-live="polite">Loading student record…</section>`;const s=d.student;return `<section class="card"><button class="button light small-btn" data-page="Students">← Back to Students</button><div class="profile-top" style="margin-top:14px"><div class="avatar profile-avatar">${s.avatar?`<img src="${s.avatar}" alt="">`:shortName(s.name)}</div><div><h2 style="margin:0">${esc(s.name)}</h2><div class="small muted">Grade ${esc(s.grade)} · Section ${esc(s.section)}</div><div class="small muted">${esc(s.email)}</div></div></div><div class="progress-grid" style="margin-top:14px"><div class="progress-item"><strong>${d.average===null?'—':d.average+'%'}</strong><span>Quiz Average</span></div><div class="progress-item"><strong>${d.average_count}</strong><span>Quizzes in Average</span></div><div class="progress-item"><strong>${d.xp}</strong><span>Total XP</span></div><div class="progress-item"><strong>${d.completed.length}/6</strong><span>Completed Lessons</span></div></div></section><section class="card"><h2 class="card-title">Quiz Results</h2>${d.attempts.length?`<div class="row-list">${d.attempts.map(a=>`<div class="lesson-row"><span class="lesson-icon ${a.passed?'done':''}">${a.passed?'✓':'!'}</span><div class="lesson-info"><strong>Lesson ${a.lesson_id}. ${esc(LESSON_NAMES[a.lesson_id-1])}</strong><small>${a.correct}/${a.total} correct · ${new Date(a.submitted_at*1000).toLocaleString()}</small></div><span class="badge ${a.passed?'passed':'failed'}">${a.score}% · ${a.passed?'Passed':'Failed'}</span></div>`).join('')}</div>`:empty('No quiz attempts have been submitted.')}</section><section class="card"><h2 class="card-title">Lesson Progress</h2><div class="progress-grid">${LESSON_NAMES.map((name,i)=>`<div class="progress-item"><strong>${d.completed.includes(i+1)?'✓':d.xp>=[0,100,250,450,700,1000][i]?'○':'🔒'}</strong><span>${esc(name)}</span></div>`).join('')}</div></section>`}
function lessonManagement(){return `<section class="card"><h2 class="card-title">Lesson Management</h2><p class="muted small">The six core General Mathematics lessons and quizzes are part of the learning path.</p><div class="row-list">${state.lessons.map((l,i)=>`<div class="lesson-row"><span class="lesson-icon">▤</span><div class="lesson-info"><strong>${i+1}. ${esc(l.title)}</strong><small>${l.xp} XP per correct answer · 10 questions · ${[0,100,250,450,700,1000][i]} XP unlock threshold</small></div><span class="badge locked">${l.unlocked?'Available':'Locked'}</span></div>`).join('')}</div></section>`}
function empty(msg){return `<div class="empty-state"><span>📘</span><p>${esc(msg)}</p></div>`}
function modalHTML(){if(state.modal==='logout')return `<div class="modal-backdrop" data-action="cancel-modal"><section class="modal" onclick="event.stopPropagation()"><div class="modal-icon">❓</div><h2>Are you sure you want to log out of your account?</h2><p>Your progress is saved in the database.</p><div class="modal-actions"><button class="button light" data-action="cancel-modal">No, stay</button><button class="button orange" data-action="logout">Yes, Log Out</button></div></section></div>`;if(state.modal==='quiz-confirm')return `<div class="modal-backdrop" data-action="cancel-modal"><section class="modal" onclick="event.stopPropagation()"><div class="modal-icon">🎯</div><h2>Are you sure you want to proceed to the quiz?</h2><p>You can submit this quiz only once. Make sure you are ready.</p><div class="modal-actions"><button class="button light" data-action="cancel-modal">No</button><button class="button orange" data-action="begin-quiz">Yes, Start Quiz</button></div></section></div>`;if(state.modal==='submit-confirm')return `<div class="modal-backdrop" data-action="cancel-modal"><section class="modal" onclick="event.stopPropagation()"><div class="modal-icon">📝</div><h2>Submit your quiz?</h2><p>This is your only attempt. You will not be able to change answers after submitting.</p><div class="modal-actions"><button class="button light" data-action="cancel-modal">Review Answers</button><button class="button orange" data-action="submit-confirm">Submit Quiz</button></div></section></div>`;if(state.modal==='garden-confirm')return `<div class="modal-backdrop" data-action="cancel-modal"><section class="modal" onclick="event.stopPropagation()"><div class="modal-icon">🌱</div><h2>Confirm Garden Action</h2><p>${state.pending.kind==='plant'?'Planting a seed costs 100 XP.':'Watering this plant costs 10 XP.'} Continue?</p><div class="modal-actions"><button class="button light" data-action="cancel-modal">Cancel</button><button class="button orange" data-action="confirm-garden">Confirm</button></div></section></div>`;if(state.modal==='game')return `<div class="modal-backdrop" data-action="cancel-modal"><section class="modal" onclick="event.stopPropagation()"><div class="modal-icon">${state.pending.icon}</div><h2>${esc(state.pending.name)}</h2><p>Solve this: What is 8 × 7?</p><div class="choice-row" style="justify-content:center"><button class="button light" data-action="game-answer" data-answer="54">54</button><button class="button" data-action="game-answer" data-answer="56">56</button><button class="button light" data-action="game-answer" data-answer="64">64</button></div></section></div>`;if(state.modal==='profile')return `<div class="modal-backdrop" data-action="cancel-modal"><section class="modal" onclick="event.stopPropagation()"><h2>Edit Profile</h2><form id="profile-form"><div class="field"><label>Full Name</label><input name="name" class="form-control" value="${esc(state.user.name)}" required maxlength="100"></div>${isTeacher()?'':`<div class="grid grid-2"><div class="field"><label>Grade Level</label><input name="grade" class="form-control" value="${esc(state.user.grade)}" required></div><div class="field"><label>Section</label><input name="section" class="form-control" value="${esc(state.user.section)}" required></div></div>`}<div class="field"><label>Profile Photo (PNG, JPG, WebP · max 500 KB)</label><input id="avatar-file" type="file" accept="image/png,image/jpeg,image/webp" class="form-control"><img id="avatar-preview" class="avatar-preview ${state.user.avatar?'':'hidden'}" src="${state.user.avatar||''}" alt="Photo preview"></div><div class="modal-actions"><button type="button" class="button light" data-action="cancel-modal">Cancel</button><button class="button">Save Changes</button></div></form></section></div>`;return ''}
function bindShell(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=async()=>{const dest=b.dataset.page;if(dest==='Logout'){state.modal='logout';render();return}await navigate(dest)});$('#menu-toggle')?.addEventListener('click',()=>$('#sidebar').classList.toggle('open'));document.querySelector('.content')?.addEventListener('click',e=>{if(e.target.closest('[data-page]')||e.target.closest('#menu-toggle'))$('#sidebar')?.classList.remove('open')});document.querySelector('.modal-backdrop')?.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop')){state.modal=null;render()}})}
async function navigate(dest){state.page=dest;state.modal=null;if(dest==='Students'||dest==='Teacher Dashboard'||dest==='Lesson Management'){try{const d=await api('/api/teacher/students');state.students=d.students;state.studentsLoaded=true}catch(e){notify(e.message)}}if(dest==='Garden'){try{state.garden=await api('/api/garden')}catch(e){notify(e.message)}}if(dest==='Profile'||dest==='Teacher Profile'){try{state.profile=await api('/api/profile');state.xp=state.profile.xp}catch(e){notify(e.message)}}render();window.scrollTo({top:0,behavior:'smooth'})}
function bindAuth(){document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>{state.page=b.dataset.auth;render()});document.querySelectorAll('[data-toggle-pass]').forEach(b=>b.onclick=()=>{const i=b.parentElement.querySelector('input');i.type=i.type==='password'?'text':'password';b.setAttribute('aria-label',i.type==='text'?'Hide password':'Show password')});$('#forgot-link')?.addEventListener('click',e=>{e.preventDefault();notify('Please contact your administrator to reset your password.')});$('#demo-fill')?.addEventListener('click',()=>{const f=$('#auth-form');f.email.value='teacher.demo@numiquest.test';f.password.value='NumiQuestDemo2026!'});$('#auth-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,d=new FormData(f),role=d.get('role'),register=state.page.endsWith('Registration');try{let r;if(register){if(d.get('password')!==d.get('confirm'))throw Error('Passwords do not match.');r=await api('/api/register',{method:'POST',body:JSON.stringify({name:d.get('name'),email:d.get('email'),password:d.get('password'),grade:d.get('grade'),section:d.get('section'),role,terms:d.get('terms')==='on'})});notify(r.message);state.page=role==='teacher'?'Teacher Login':'Student Login';render();return}r=await api('/api/login',{method:'POST',body:JSON.stringify({email:d.get('email'),password:d.get('password'),role})});state.user=r.user;state.page=role==='teacher'?'Teacher Dashboard':'Home';await sync();if(isTeacher()){const st=await api('/api/teacher/students');state.students=st.students;state.studentsLoaded=true}render()}catch(err){notify(err.message)}})}
function bindPage(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>doAction(b.dataset.action,b.dataset));document.querySelectorAll('input[name^="q"]').forEach(x=>x.onchange=()=>{const i=Number(x.name.slice(1));state.quizAnswers[i]=Number(x.value);x.closest('.question-block').querySelectorAll('.quiz-option').forEach(el=>el.classList.remove('selected'));x.closest('.quiz-option').classList.add('selected')});$('#complete-lesson')?.addEventListener('click',async()=>{if(!$('#lesson-read').checked){notify('Please read the lesson and confirm before continuing.');return}try{await api(`/api/lessons/${state.openLesson}/complete`,{method:'POST',body:'{}'});await sync();state.modal='quiz-confirm';render()}catch(e){notify(e.message)}});$('#submit-quiz')?.addEventListener('click',submitQuiz);$('#settings-form')?.addEventListener('submit',saveSettings);$('#student-search')?.addEventListener('input',e=>{state.search=e.target.value;renderKeepFocus('student-search')});$('#status-filter')?.addEventListener('change',e=>{state.status=e.target.value;render()});$('#password-form')?.addEventListener('submit',changePassword);$('#profile-form')?.addEventListener('submit',saveProfile);$('#avatar-file')?.addEventListener('change',previewAvatar);}
function renderKeepFocus(id){const input=$('#'+id),pos=input.selectionStart;const value=input.value;const y=window.scrollY;const app=$('#app');app.innerHTML=layout(pageContent());bindShell();bindPage();const next=$('#'+id);next?.focus();next?.setSelectionRange(pos,pos);window.scrollTo(0,y)}
async function submitQuiz(){const missing=state.quizAnswers.map((a,i)=>a===null?i+1:null).filter(Boolean);const w=$('#quiz-warning');if(missing.length){w.innerHTML=`<div class="notice">❗ Please answer questions: ${missing.join(', ')}.</div>`;document.querySelector(`[name="q${missing[0]-1}"]`)?.scrollIntoView({behavior:'smooth',block:'center'});return}state.modal='submit-confirm';render()}
function doAction(action,d){if(action==='open-lesson'){const l=state.lessons[Number(d.index)];if(!l?.unlocked){notify('Earn more XP to unlock this lesson.');return}if(l.attempted){state.openLesson=l.id;state.result=l.attempt;state.page='Quiz Result';render();return}state.openLesson=l.id;state.page='Lesson';render()}else if(action==='begin-quiz'){beginQuiz()}else if(action==='cancel-modal'){state.modal=null;render()}else if(action==='logout'){logout()}else if(action==='show-result'){const l=state.lessons[Number(d.index)];state.openLesson=l.id;state.result=l.attempt;state.quiz=null;loadQuizReview(l.id)}else if(action==='edit-profile'){state.modal='profile';render()}else if(action==='student-detail'){loadStudentDetail(Number(d.id))}else if(action==='play-game'){const i=Number(d.index);state.pending={game:i,icon:GAMES[i][0],name:GAMES[i][1]};state.modal='game';render()}else if(action==='game-answer'){playGame(Number(state.pending.game),Number(d.answer))}else if(action==='garden'){state.pending={kind:d.kind,plot:Number(d.index)};state.modal='garden-confirm';render()}else if(action==='confirm-garden'){gardenAction()}else if(action==='submit-confirm'){state.modal=null;submitFinal()} }
async function beginQuiz(){state.modal=null;try{state.quiz=await api(`/api/lessons/${state.openLesson}/quiz`);state.quizAnswers=Array(10).fill(null);state.page='Quiz';render();window.scrollTo(0,0)}catch(e){notify(e.message);await sync();state.page='Lessons';render()}}
async function submitFinal(){try{const r=await api(`/api/lessons/${state.openLesson}/quiz`,{method:'POST',body:JSON.stringify({answers:state.quizAnswers})});state.result=r;await sync();state.page='Quiz Result';render();window.scrollTo(0,0)}catch(e){notify(e.message);await sync();state.page='Lessons';render()}}
async function loadQuizReview(id){try{const r=await api(`/api/lessons/${id}/quiz-review`);state.quiz=r;state.result=r.attempt}catch{}state.page='Quiz Result';render()}
async function loadStudentDetail(id){try{state.studentDetail=await api(`/api/teacher/students/${id}`);state.page='Student Details';render()}catch(e){notify(e.message)}}
async function playGame(game,answer){try{await api('/api/games/answer',{method:'POST',body:JSON.stringify({game,answer})});state.modal=null;await sync();notify('Correct! +10 XP ⭐');state.page='Games';render()}catch(e){notify(e.message)}}
async function gardenAction(){const p=state.pending;try{await api('/api/garden/action',{method:'POST',body:JSON.stringify({plot:p.plot,action:p.kind})});state.garden=await api('/api/garden');state.xp=state.garden.xp;state.modal=null;render();notify(p.kind==='plant'?'Seed planted! −100 XP':'Plant grew! −10 XP')}catch(e){state.modal=null;render();notify(e.message)}}
async function saveSettings(e){e.preventDefault();const d=new FormData(e.currentTarget);try{await api('/api/settings',{method:'POST',body:JSON.stringify({language:d.get('language'),theme:d.get('theme')})});state.user.language=d.get('language');state.user.theme=d.get('theme');render();notify('Your settings have been saved.')}catch(err){notify(err.message)}}
async function changePassword(e){e.preventDefault();const d=new FormData(e.currentTarget);if(d.get('new_password')!==d.get('confirm_password')){notify('New passwords do not match.');return}try{await api('/api/password',{method:'POST',body:JSON.stringify({current_password:d.get('current_password'),new_password:d.get('new_password')})});e.target.reset();notify('Password updated successfully.')}catch(err){notify(err.message)}}
let pendingAvatar='';
function previewAvatar(e){const f=e.target.files?.[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>500*1024){e.target.value='';notify('Choose a PNG, JPG, or WebP file under 500 KB.');return}const reader=new FileReader();reader.onload=()=>{pendingAvatar=reader.result;const p=$('#avatar-preview');p.src=pendingAvatar;p.classList.remove('hidden')};reader.readAsDataURL(f)}
async function saveProfile(e){e.preventDefault();const d=new FormData(e.currentTarget);try{await api('/api/profile',{method:'POST',body:JSON.stringify({name:d.get('name'),grade:d.get('grade')||state.user.grade,section:d.get('section')||state.user.section,avatar:pendingAvatar||state.user.avatar||''})});pendingAvatar='';await sync();state.modal=null;render();notify('Profile updated.')}catch(err){notify(err.message)}}
async function logout(){const role=state.user?.role;try{await api('/api/logout',{method:'POST',body:'{}'})}catch{}state.user=null;state.modal=null;state.lessons=[];state.students=[];state.result=null;state.page=role==='teacher'?'Teacher Login':'Student Login';history.replaceState(null,'',location.pathname);render()}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){state.modal=null;render()}});
start();

